 void calculate(boolean save){if(busy)return;try{String input=inputRequest();prefs.edit().putString("date",draftDate).putString("longitude",draftLongitude).putInt("sex",draftSex).putBoolean("solar",draftSolar).putString("topic",topic).putBoolean("lunar",draftLunar).putBoolean("leap",draftLeap).putBoolean("fixLeap",draftFixLeap).apply();runChart(input,topic,true,save);}catch(Exception e){message("请检查输入",e.getMessage());}}
