 String chartSummary(){JSONObject info=chart.optJSONObject("其他信息");StringBuilder b=new StringBuilder("事项："+chartTopic+"\n");for(String k:new String[]{"钟表时间","真太阳时","性别","五行局","命宫","身宫","命主","身主"}){if(prefs.getBoolean("hideTime",false)&&k.contains("时"))continue;b.append(k).append("：").append(info.optString(k)).append('\n');}for(String branch:BRANCH){JSONObject p=chart.optJSONObject("十二宫信息").optJSONObject(branch);b.append('\n').append(branch).append(" · ").append(palaceName(p.optString("宫"))).append("\n").append(palaceText(p));}return b.append(flow.summary()).toString();}
